std::vector<Node> nodes;
nodes.reserve(rt.number_of_vertices());

for (auto vit = rt.finite_vertices_begin(); vit != rt.finite_vertices_end(); ++vit) {
    Node node;

    // Position
    auto p = vit->point();
    node.position = { CGAL::to_double(p.x()), CGAL::to_double(p.y()), CGAL::to_double(p.z()) };

    // Mass (weight of the vertex in Regular_triangulation_3)
    node.mass = CGAL::to_double(vit->weight());

    // Velocity
    // The velocity is calculated based on the cell associated with the vertex.
    // In the context of Adhesion, we typically use the velocity of a cell incident to the vertex.
    RT::Cell_handle ch = rt.incident_cell(vit);
    if (ch != nullptr) {
        Vector v = velocity(ch);
        node.velocity = { v.x(), v.y(), v.z() };

        // Node Type classification based on edge count of the incident cell
        int count = edge_count(ch, threshold);
        node.node_type = type_from_edge_count(count);
    } else {
        node.velocity = { 0.0, 0.0, 0.0 };
        node.node_type = UNDEFINED_NODE_TYPE;
    }

    nodes.push_back(node);
}

return nodes;

